<?php declare(strict_types=1); $e = static fn($v): string => htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); $money = static fn($v): string => number_format((float)$v, 0, ',', '.') . ' ₫'; ?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phiếu đơn hàng <?= $e($order->orderCode) ?></title><style>body{font:16px system-ui,sans-serif;color:#202842;max-width:900px;margin:2rem auto;padding:0 1rem}table{width:100%;border-collapse:collapse}th,td{padding:.7rem;text-align:left;border-bottom:1px solid #ddd}th:last-child,td:last-child{text-align:right}@media print{button{display:none}body{margin:0}}</style></head><body><button type="button" onclick="window.print()">In / Lưu PDF</button><h1>Phiếu đơn hàng nội bộ</h1><p>Không phải hóa đơn điện tử.</p><p><strong><?= $e($order->orderCode) ?></strong> · <?= $e($order->createdAt) ?></p><p><?= $e($order->customerName) ?> · <?= $e($order->customerPhone) ?><br><?= $e($order->customerAddress) ?></p><table><thead><tr><th>Sản phẩm</th><th>Đơn giá</th><th>Số lượng</th><th>Thành tiền</th></tr></thead><tbody><?php foreach($order->items as $item): ?><tr><td><?= $e($item->productName) ?></td><td><?= $money($item->unitPrice) ?></td><td><?= (int)$item->quantity ?></td><td><?= $money($item->subtotal) ?></td></tr><?php endforeach; ?></tbody></table><?php foreach($operations['adjustments'] as $adjustment): ?><p>Điều chỉnh: <?= $money($adjustment['amount_vnd']) ?> · <?= $e($adjustment['reason']) ?></p><?php endforeach; ?><p><strong>Tổng đơn: <?= $order->formattedTotal() ?></strong></p><p>Đã thu ròng: <?= $money($operations['net_paid']) ?> · Còn phải thu: <?= $money(max(0, $order->totalAmount - $operations['net_paid'])) ?></p><p>Ghi chú: <?= $e($order->note) ?></p></body></html>
